  "claims": [
    {
      "text": "Yes. Under subsection 92(5), if the right or interest relied on to make a non-use application becomes vested in another person, that person may be substituted as the applicant on giving notice of the relevant facts to the Registrar or the court, as the case requires.",
      "quotes": [
        {
          "ref": "TMA1995/s92",
          "quote": "(5) If the right or interest on which a person relied to make a non-use application becomes vested in another person, the other person may, on giving notice of the relevant facts to the Registrar or the court (as the case requires), be substituted for the first-mentioned person as the applicant."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual states that the application may proceed in the other person’s name provided the relevant right or interest has passed to them and the Registrar or the court has been notified of that fact in writing.",
      "quotes": [
        {
          "ref": "TMM/Part48/2/2/1",
          "quote": "Subsection 92(5) provides that, under certain circumstances, a non-use application may proceed in the name of a person other than the person who filed the application. This may happen provided that the right or interest, upon which the person who filed the application for removal relied, has passed to the other person, and the Registrar or the court has been notified in writing of this fact."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The express requirement for written notification comes from the supplied Manual passage; subsection 92(5) itself requires notice of the relevant facts but does not expressly specify writing.",
      "quotes": [
        {
          "ref": "TMM/Part48/2/2/1",
          "quote": "the Registrar or the court has been notified in writing of this fact."
        },
        {
          "ref": "TMA1995/s92",
          "quote": "on giving notice of the relevant facts to the Registrar or the court (as the case requires)"
        }
      ],
      "authority": "both"
    }
  ],
  "declined": false,
